"use strict";

// C08: the throwing call is one hop away, inside a local wrapper whose
// every modeled path reaches it.
//
//     function viaHelper() { bail(); }
//     viaHelper();
//
// The bound is two wrapper hops, documented in module-model.ts's
// MAX_CALLABLE_ABRUPT_SUMMARY_DEPTH. This module uses one; `valid.js`
// carries the wrappers that must NOT be summarized -- a conditional path,
// a return path, a caught throw, a deferred callback and a recursive one.
const danger = require("./danger");

function dangerousOp(input) {
  return danger.explode(input);
}

function safeOp(input) {
  return "safe:" + input;
}

function bail() {
  throw new Error("boom");
}

// No conditional, no return, no catch: every path through this body
// reaches `bail()`, so calling it always propagates the throw.
function viaHelper() {
  bail();
}

if (process.env.FIXTURE_LIB_MODE === "fast") {
  module.exports = dangerousOp;
  viaHelper();
}

module.exports = safeOp;
